# Verification functions
def count_words(text):
    return len(text.split())

def verify_all():
    print(f"Verifying {len(chapters)} chapters...")
    shingles = {}
    total_words_all = 0
    all_paras_set = set()
    problems = []

    for filename, data in chapters.items():
        title = data["title"]
        paras = data["paras"]
        num_paras = len(paras)
        print(f"\n--- Checking {filename} ---")
        print(f"Title: {title}")
        print(f"Paragraph count: {num_paras}")
        if num_paras < 16 or num_paras > 18:
            problems.append(f"{filename}: para count {num_paras} must be 16 to 18")

        ch_words = count_words(title)
        paras_word_counts = []
        for idx, p in enumerate(paras, 1):
            if "\n" in p or "\r" in p:
                problems.append(f"{filename} para {idx}: contains embedded newline")
            
            # Markdown formatting check
            if re.search(r'(\*\*|__|`|^\s*[-*+]\s|^\s*\d+\.\s|^\s*>|^\s*#)', p):
                problems.append(f"{filename} para {idx}: contains markdown formatting")

            pw = count_words(p)
            paras_word_counts.append(pw)
            ch_words += pw

            if pw < 65:
                problems.append(f"{filename} para {idx}: too short ({pw} words, must be 65-135)")
            if pw > 135:
                problems.append(f"{filename} para {idx}: too long ({pw} words, must be 65-135)")

            p_lower = p.lower()
            for b in BANNED:
                if re.search(b, p, re.IGNORECASE if 'AI Businesses' not in b else 0):
                    problems.append(f"{filename} para {idx}: contains banned term matching {b}")

            # Check duplicate paragraph
            if p_lower in all_paras_set:
                problems.append(f"{filename} para {idx}: duplicate paragraph across book")
            all_paras_set.add(p_lower)

            # Check shingles (12-word sequences)
            words_clean = re.sub(r"[^a-z0-9' ]", "", p_lower).split()
            for k in range(0, len(words_clean) - 11, 6):
                sh = " ".join(words_clean[k:k+12])
                shingles[sh] = shingles.get(sh, 0) + 1

        print(f"Para word counts: min={min(paras_word_counts)}, max={max(paras_word_counts)}, avg={sum(paras_word_counts)/len(paras_word_counts):.1f}")
        print(f"Total chapter words: {ch_words}")
        if ch_words < 1550 or ch_words > 1850:
            problems.append(f"{filename}: total words {ch_words} outside 1,550-1,850 range")
        total_words_all += ch_words

    rep = [k for k, v in shingles.items() if v > 2]
    if len(rep) > 5:
        problems.append(f"Repeated 12-word phrases across chapters: {len(rep)} > 5. Examples: {rep[:3]}")

    print(f"\n==========================================")
    print(f"TOTAL WORDS ACROSS 7 CHAPTERS: {total_words_all}")
    if problems:
        print(f"FAIL: {len(problems)} problems found:")
        for p in problems:
            print(" -", p)
        return False
    else:
        print("ALL 7 CHAPTERS PASS INTERNAL VALIDATION!")
        return True

def write_files():
    for filename, data in chapters.items():
        title = data["title"]
        paras = data["paras"]
        content = f"# {title}\n\n" + "\n\n".join(paras) + "\n"
        filepath = os.path.join(DIR, filename)
        with open(filepath, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"Written: {filepath}")

if __name__ == "__main__":
    if verify_all():
        write_files()
        print("\nAll files written successfully!")
    else:
        print("\nFix problems before writing.")
